-- REVIEW ONLY, rollback-only, external DEV only. Apply reviewed blog proposal first.
BEGIN;
CREATE FUNCTION pg_temp.assert_true(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; END $$;
SELECT pg_temp.assert_true(public.blog_document_valid('{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Safe article"}]}]}'::jsonb),'valid paragraph');
SELECT pg_temp.assert_true(NOT public.blog_document_valid('{"type":"doc","content":[{"type":"script","content":[]}]}'::jsonb),'script denied');
SELECT pg_temp.assert_true(NOT public.blog_document_valid('{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x","marks":[{"type":"link","attrs":{"href":"javascript:alert(1)"}}]}]}]}'::jsonb),'javascript denied');
SELECT pg_temp.assert_true(NOT public.blog_document_valid('{"type":"doc","content":[],"onclick":"evil"}'::jsonb),'event attributes denied');
SELECT pg_temp.assert_true(NOT public.blog_document_valid('{"type":"doc","content":[{"type":"text","text":"wrong nesting"}]}'::jsonb),'invalid nesting denied');
SELECT pg_temp.assert_true(NOT has_function_privilege('anon','public.save_blog_post(jsonb)','EXECUTE'),'anonymous post save denied');
INSERT INTO auth.users(id,email) VALUES('b7100000-0000-4000-8000-000000000001','blog-admin-test@example.invalid'),('b7100000-0000-4000-8000-000000000002','blog-seller-test@example.invalid');
INSERT INTO public.user_roles(user_id,role) VALUES('b7100000-0000-4000-8000-000000000001','admin');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b7100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
SELECT public.save_blog_post(jsonb_build_object('id','b7200000-0000-4000-8000-000000000001','title','Rollback test draft','slug','rollback-test-draft-b720','excerpt','','content','{"type":"doc","content":[{"type":"paragraph","content":[]}]}'::jsonb,'status','draft','category_id',NULL,'tags','[]'::jsonb,'image_alt','','seo_title','','seo_description',''));
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'admin reads own draft');
SELECT set_config('request.jwt.claims','{"sub":"b7100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'seller cannot read draft');
DO $$ BEGIN PERFORM public.save_blog_post('{}'::jsonb);RAISE EXCEPTION 'FAIL: seller saved post';EXCEPTION WHEN insufficient_privilege THEN NULL;END $$;
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'anonymous draft hidden');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b7100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
UPDATE public.blog_posts SET status='published' WHERE id='b7200000-0000-4000-8000-000000000001';
SELECT pg_temp.assert_true((SELECT published_at=now() FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'publication timestamp stamped');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'anonymous published read');
RESET ROLE;
UPDATE public.blog_posts SET status='draft' WHERE id='b7200000-0000-4000-8000-000000000001';
SET LOCAL ROLE anon;
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.blog_posts WHERE id='b7200000-0000-4000-8000-000000000001'),'unpublish hides post immediately');
RESET ROLE;
DO $$ BEGIN RAISE NOTICE 'BLOG CMS ROLLBACK CHECKS PASSED (if this notice is reached). Storage endpoint and concurrent publication checks still require separate verification.'; END $$;
ROLLBACK;
